record.field:
from datetime import date
overdue = env['maintenance.equipment'].search([
    ('ppm_overdue', '=', True),
    ('active', '=', True),
])
for equip in overdue:
    template = env.ref('dean_group_mfg.mail_template_ppm_overdue', raise_if_not_found=False)
    if template:
        template.send_mail(equip.id, force_send=True)

held = env['mrp.production'].search([
    ('quality_hold', '=', True),
    ('state', 'not in', ['done', 'cancel']),
])
for mo in held:
    mo.message_post(
        body=f"⚠️ Reminder: Manufacturing order {mo.name} is on Quality Hold. Reason: {mo.quality_hold_reason or 'Not specified'}",
        message_type='notification',
        subtype_xmlid='mail.mt_note',
    )
